<?php
declare(strict_types=1);
require_once __DIR__ . '/_helper.php';
if (!isset($_GET['manual_sesi'])) { absensi_get_or_create_hari_ini($pdo); }
$cari=trim((string)($_GET['cari']??''));
$status=(string)($_GET['status']??'semua'); if(!in_array($status,['semua','draft','aktif','ditutup'],true))$status='semua';
$perPage=(int)($_GET['per_page']??20);if(!in_array($perPage,[5,10,20,50,100],true))$perPage=20;$page=max(1,(int)($_GET['page']??1));
$where=["ja.kategori='kehadiran'"]; $params=[];
if($status!=='semua'){ $where[]='s.status=?';$params[]=$status; }
if($cari!==''){ $where[]='(s.nama_sesi LIKE ? OR ja.nama LIKE ? OR js.nama LIKE ?)';$q="%$cari%";array_push($params,$q,$q,$q); }
$whereSql=$where?'WHERE '.implode(' AND ',$where):'';
$countSt=$pdo->prepare("SELECT COUNT(*) FROM sesi_absensi s JOIN jenis_absensi ja ON ja.id=s.jenis_absensi_id LEFT JOIN jenis_sholat js ON js.id=s.jenis_sholat_id $whereSql");$countSt->execute($params);$total=(int)$countSt->fetchColumn();$totalPages=max(1,(int)ceil($total/$perPage));if($page>$totalPages)$page=$totalPages;$offset=($page-1)*$perPage;
$st=$pdo->prepare("SELECT s.*,ta.nama tahun_nama,se.nama semester_nama,ja.nama jenis_nama,ja.kategori,js.nama sholat_nama,(SELECT COUNT(*) FROM absensi a WHERE a.sesi_id=s.id) jumlah_scan FROM sesi_absensi s JOIN tahun_pelajaran ta ON ta.id=s.tahun_pelajaran_id JOIN semester se ON se.id=s.semester_id JOIN jenis_absensi ja ON ja.id=s.jenis_absensi_id LEFT JOIN jenis_sholat js ON js.id=s.jenis_sholat_id $whereSql ORDER BY s.tanggal DESC,s.id DESC LIMIT $perPage OFFSET $offset");$st->execute($params);$rows=$st->fetchAll();
$jamMulaiPulang=absensi_setting_value($pdo,'jam_mulai_pulang','13:00') ?? '13:00';
$jamSelesaiPulang=absensi_setting_value($pdo,'jam_selesai_pulang','16:30') ?? '16:30';
$batasFinalisasi=absensi_batas_finalisasi($pdo);
$page_title='Sesi Absensi';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
?>
<main class="main"><header class="topbar"><div class="topbar-title">Sesi Absensi</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content attendance-module">
<div class="page-header"><div><h1>Absensi Kehadiran Otomatis</h1><p>Sesi kehadiran dibuat otomatis sesuai jadwal sekolah.</p></div><div class="page-header-actions"><a class="btn btn-primary" title="Kehadiran" href="<?=BASE_URL?>absensi/daftar.php?sesi_id=<?= (int)(absensi_get_or_create_hari_ini($pdo)['id'] ?? 0) ?>">Kehadiran Hari Ini</a><a class="btn btn-info attendance-scan-btn" href="<?=BASE_URL?>scanner/index.php"><i class="bi bi-qr-code-scan"></i> Scanner QR</a></div></div>
<form method="get" class="filter-bar"><input class="form-control" type="search" name="cari" value="<?=e($cari)?>" placeholder="Cari nama sesi, jenis, atau sholat..."><select class="form-control" name="status"><option value="semua" <?=$status==='semua'?'selected':''?>>Semua status</option><option value="draft" <?=$status==='draft'?'selected':''?>>Draft</option><option value="aktif" <?=$status==='aktif'?'selected':''?>>Aktif</option><option value="ditutup" <?=$status==='ditutup'?'selected':''?>>Ditutup</option></select><select class="form-control" name="per_page"><option value="5" <?= $perPage===5?'selected':'' ?>>5</option><option value="10" <?= $perPage===10?'selected':'' ?>>10</option><option value="20" <?= $perPage===20?'selected':'' ?>>20</option><option value="50" <?= $perPage===50?'selected':'' ?>>50</option><option value="100" <?= $perPage===100?'selected':'' ?>>100</option></select><button class="btn btn-secondary"><i class="bi bi-funnel"></i> Terapkan</button></form>
<?php if(isset($_GET['saved'])):?><div class="alert alert-success"><?=e((string)$_GET['saved'])?></div><?php endif;?><?php if(isset($_GET['error'])):?><div class="alert alert-danger"><?=e((string)$_GET['error'])?></div><?php endif;?><div class="dashboard-table-card"><div class="table-responsive"><table class="data-table"><thead><tr><th>Tanggal</th><th>Nama Sesi</th><th>Konteks</th><th>Jam Datang</th><th>Jadwal Pulang</th><th>Batas Finalisasi</th><th>Status</th><th>Scan</th><th>Aksi</th></tr></thead><tbody>
<?php if(!$rows):?><tr><td colspan="9" class="empty-state">Belum ada sesi absensi.</td></tr><?php else: foreach($rows as $r):?><tr><td><?=e($r['tanggal'])?></td><td><strong><?=e($r['nama_sesi'])?></strong><br><small><?=e($r['tahun_nama'])?> · <?=e($r['semester_nama'])?></small></td><td><?=e($r['jenis_nama'])?><?php if($r['sholat_nama']):?> · <?=e($r['sholat_nama'])?><?php endif;?></td><td><?=e(substr($r['jam_mulai'],0,5))?>–<?=e(substr($r['jam_selesai'],0,5))?></td><td><?= $r['kategori']==='kehadiran' ? e($jamMulaiPulang).'–'.e($jamSelesaiPulang) : '—' ?></td><td><?= $r['kategori']==='kehadiran' ? e($batasFinalisasi).' WIB' : '—' ?></td><td><span class="status-badge status-<?=e($r['status'])?>"><?=e(ucfirst($r['status']))?></span></td><td><?= (int)$r['jumlah_scan'] ?></td><td><div class="table-actions"><a class="btn btn-secondary btn-sm btn-icon-sm" title="Detail sesi" aria-label="Detail sesi" href="<?=BASE_URL?>absensi/detail.php?id=<?=(int)$r['id']?>"><i class="bi bi-eye" aria-hidden="true"></i></a><?php if($r['kategori']==='kehadiran'):?><a class="btn btn-secondary btn-sm btn-icon-sm" title="Daftar kehadiran" aria-label="Daftar kehadiran" href="<?=BASE_URL?>absensi/daftar.php?sesi_id=<?=(int)$r['id']?>"><i class="bi bi-people" aria-hidden="true"></i></a><?php endif;?><?php if($r['status']==='aktif'):?><a class="btn btn-primary btn-sm btn-icon-sm" title="Scanner absensi" aria-label="Scanner absensi" href="<?=BASE_URL?>scanner/index.php?sesi_id=<?=(int)$r['id']?>"><i class="bi bi-qr-code-scan" aria-hidden="true"></i></a><?php endif;?><?php if($r['kategori']==='kehadiran' && $r['status']!=='ditutup'):?><form method="post" action="<?=BASE_URL?>absensi/delete.php" style="display:inline" onsubmit="return confirm('Hapus sesi kehadiran ini beserta transaksi absensinya?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn btn-danger btn-sm btn-icon-sm" type="submit" title="Hapus" aria-label="Hapus"><i class="bi bi-trash3" aria-hidden="true"></i></button></form><?php endif;?></div></td></tr><?php endforeach;endif;?></tbody></table></div></div><div class="pagination-bar"><div class="text-muted">Menampilkan <?= $total ? ($offset+1).'–'.min($offset+$perPage,$total) : '0' ?> dari <?= $total ?> sesi</div><div class="pagination"><?php for($pg=1;$pg<=$totalPages;$pg++):?><a class="btn btn-sm <?= $pg===$page?'btn-primary':'btn-secondary' ?>" href="?cari=<?=rawurlencode($cari)?>&status=<?=rawurlencode($status)?>&per_page=<?=$perPage?>&page=<?=$pg?>"><?=$pg?></a><?php endfor;?></div></div>
</section></main><?php require_once __DIR__.'/../layouts/footer.php';?>
